package stdsyms

import "reflect"

// NativeTable is the native symbol table of a package outside the standard
// library that the host links: its exported functions, types and variables
// (pointers), and the version of its module in yaegi v2's go.mod when the table
// was generated. Constants are not in it.
type NativeTable struct {
	Version string
	Funcs   map[string]reflect.Value
	Types   map[string]reflect.Type
	Vars    map[string]reflect.Value
}

// XSysUnix is the table of golang.org/x/sys/unix on this platform
// (xsys_unix_GOOS_GOARCH.go, generated by cmd/stdsyms), nil on a platform
// without one. The VM gives it to a plugin instead of running the package
// from source, with a read-only subset for restricted plugins (vm/xsys.go).
var XSysUnix *NativeTable
